        socks.extend([i] * cnt)

    # g(L): min total weirdness when every sock in L is paired (len(L) even).
    def g(L):
        if not L:
            return 0
        best = None
        for j in range(1, len(L)):
            rest = L[1:j] + L[j + 1:]
            cand = abs(L[0] - L[j]) + g(rest)
            if best is None or cand < best:
                best = cand
        return best

    # f(L): min total weirdness leaving len(L) % 2 socks unpaired.
    def f(L):
        if len(L) % 2 == 0:
            return g(L)
        # odd length: exactly one sock is unpaired
        best = None
        # option 1: sock 0 is the unpaired one, rest all paired
        cand = g(L[1:])
        best = cand
        # option 2: sock 0 is paired with some j, unpaired one lies elsewhere
        for j in range(1, len(L)):
            rest = L[1:j] + L[j + 1:]
            cand = abs(L[0] - L[j]) + f(rest)
            if cand < best:
                best = cand
        return best

